/// <summary>
/// The <c>AVAWHSWorkExceptionDbt_Extension</c> represents a extension of WHSWorkException table.
/// </summary>
/// <remarks>
/// AVA_6726_8001_RFFull_WorkLockMode
/// </remarks>
[
    ExtensionOf(tableStr(WHSWorkException))
]
final class AVAWHSWorkExceptionDbt_Extension
{
}

Method.Source:
/// <summary>
/// Check if the exception code is a record of type AVAFullPick an has to be locked
/// </summary>
/// <param name = "_workExceptionCode">
/// to checked WHSWorkExceptionCode
/// </param>
/// <returns>
/// true if the code exists and locked wor are checked otherwise false
/// </returns>
public static boolean avaIsWorkFullLockMode(WHSWorkExceptionCode _workExceptionCode)
{
    WHSWorkException    workException;
    boolean             ret;

    select firstonly workException
        where workException.ExceptionType == WHSExceptionType::AVAFullPick
           && workException.WorkExceptionCode == _workExceptionCode;

    if (workException
        && workException.AVAWorkFullLockMode == NoYes::Yes)
    {
        ret = true;
    }

    return ret;
}

/// <summary>
/// Check if AVAFullPick exists as type
/// </summary>
/// <returns>
/// Check if ExceptionType is AVAFullPick exists as type
/// </returns>
public static boolean avaHasWorkFullLockMode()
{
    WHSWorkException    workException;
    boolean             ret;

    select firstonly workException
        where workException.ExceptionType == WHSExceptionType::AVAFullPick;

    if (workException)
    {
        ret = true;
    }

    return ret;
}

/// <summary>
///  Contains code to be executed when a field of the record has to validate
/// </summary>
/// <param name = "_fieldToCheck">
/// fieldId to check
/// </param>
/// <returns>
/// true is valid otherwise false
/// </returns>
public boolean validateField(FieldId _fieldToCheck)
{
    boolean ret;

    ret = next validateField(_fieldToCheck);

    switch (_fieldToCheck)
    {
        case fieldNum(WHSWorkException, AVAWorkFullLockMode):
            if (this.ExceptionType != WHSExceptionType::AVAFullPick)
            {
                ret = checkFailed("@NDX:AVANoWorkLockSelect");
            }
            break;
    }

    return ret;
}

/// <summary>
/// Contains code to be executed when a field of the record is modified.
/// </summary>
/// <param name="_fieldId">
/// Name of the modified field.
/// </param>
public void modifiedField(FieldId _fieldId)
{

    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(WHSWorkException, ExceptionType):
            this.AVAWorkFullLockMode = NoYes::No;
            break;
    }
}
